/*=============== ADA Complaince styling ===================*/
#skipToContent {
  position: fixed;
  z-index: -99;
  top: 10px;
  left: 10px;
  opacity: 0;
  &:focus {
    opacity: 4;
    z-index: 99999;
  }
}

.nonlink {
  cursor: default;
  pointer-events: auto;
  @include media-breakpoint-up(md) {
    pointer-events: none;
  }
  &:hover {
    text-decoration: none;
  }
  &.fax {
    &:hover {
      text-decoration: none !important;
    }
  }
}

.lightbox {
  //display: inline-block;
  &.tse-remove-border {
    outline: none !important;
    &:focus {
      outline: none !important;
    }
  }
}

.tse-remove-border {
  outline: none !important;
  &:focus {
    outline: none !important;
  }
}

.btn-primary,
.btn-primary,
.show > .btn-primary.dropdown-toggle {
  &.tse-remove-border {
    box-shadow: none !important;
    &:focus {
      box-shadow: none !important;
    }
  }
}

.no-touch {
  &.mfg-popup-open {
    margin-right: 17px;
    .pillarpage-linklist-module.stuck,
    .sh-sticky-wrap.stuck {
      // padding-right: 17px;
      width: calc(100% - 17px);
    }
    #back-to-top {
      right: rem(67);
    }
  }
}

