/*============= Content on Carousel =================*/
.content-on-carousel {
  position: relative;
  > .container {
    position: relative;
    z-index: 1;
  }

  .carousel-content {
    padding: 0 2.5rem 3rem 2.5rem;
  }
  .carousel {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
  }

  .carousel-inner {
    width: 100%;
    height: 100%;
    position: relative;
    overflow: hidden;
    .carousel-item {
      min-height: 100%;
    }
  }

  .carousel-indicators {
    position: absolute;
    right: 0;
    left: 0;
    bottom: rem(19);
    z-index: 15;
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: center;
    -ms-flex-pack: center;
    justify-content: center;
    padding-left: 0;
    margin-right: 15%;
    margin-left: 15%;
    list-style: none;

    li {
      -webkit-box-sizing: content-box;
      box-sizing: content-box;
      -webkit-box-flex: 0;
      -ms-flex: 0 1 auto;
      flex: 0 1 auto;
      width: 14px;
      height: 14px;
      margin-right: 3px;
      margin-left: 2px;
      text-indent: -999px;
      cursor: pointer;
      background-color: transparent;
      background-clip: padding-box;
      border: 0;
      background-color: $white;
      opacity: 1;
      -webkit-transition: opacity 0.6s ease;
      transition: opacity 0.6s ease;
      padding: 0;
      border-radius: 50%;
      &.active {
        background-color: $orange;
      }
      &:focus {
        outline: 2px solid $primary;
        outline-offset: -2px;
      }
    }
  }

  .carousel-control-prev {
    &:focus {
      outline: 2px solid $primary;
      outline-offset: -2px;
    }
  }

  .carousel-control-next {
    &:focus {
      outline: 2px solid $primary;
      outline-offset: -2px;
    }
  }
}

