.bootstrap-tabs {
  .tab-content {
    width: 100%;
    @include media-breakpoint-up(md) {
      padding: rem(50) rem(20);
      background-color: #fafafa;
    }
  }

  .nav-tabs {
    width: 100%;
    border-radius: 0;
    border-bottom: 0;
    a:focus {
      position: relative;
      outline: 2px solid;
      outline-offset: -2px;
    }
  }
  .panel-title,
  .nav-tabs li {
    width: 25%;
    text-transform: uppercase;
    color: white;
    font-weight: 700;
    border: 0;
    border-right-color: white;
    border-right-width: 2px;
    border-right-style: solid;
    border-radius: 0;

    a {
      padding: rem(30) rem(20);
      border: none;
      display: block;
      background-color: $primary;
      color: $white;
      text-decoration: none;
      position: relative;
      &:after {
        content: "+";
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        right: rem(20);
      }
      &:focus,
      &:hover {
        border: none !important;
        text-decoration: none;
      }

      &.active {
        background-color: #fafafa;
        color: $primary;
      }

      &[aria-expanded="true"] {
        background-color: #fafafa;
        color: $primary;
        &:after {
          content: "-";
        }
      }
    }

    @include media-breakpoint-up(md) {
      text-align: center;
      a {
        &:after {
          display: none;
        }
      }
    }
  }

  .panel-title {
    width: 100%;
  }

  @media (min-width: 768px) {
    .panel-heading {
      display: none;
    }

    .panel {
      border: none;
      box-shadow: none;
    }

    .panel-collapse {
      height: auto;

      &.collapse {
        display: block;
      }
    }
  }

  @media (max-width: 767px) {
    .bt-tab-img {
      margin-bottom: rem(30);
    }

    .tab-content {
      .tab-pane {
        display: block;
      }
    }

    .nav-tabs {
      display: none;
    }

    .panel-title a {
      display: block;
    }

    .panel {
      margin: 0;
      box-shadow: none;
      border-radius: 0;
      margin-top: -2px;
    }

    .panel-collapse {
      margin-bottom: rem(20);
    }
  }
}

