.innerpage-carousel {
  max-width: rem(467);
  margin: 0;
  margin: auto;
  margin-bottom: em(16);
  width: 100%;
  a.lightbox {
    &:focus:not(:active):not(:hover) {
      outline-offset: -2px;
    }
  }
  .slider-nav {
    width: 100%;
    /*padding: 0 12%;*/
    padding: rem(5) 15% 0 0;
    position: relative;
    .slick-track {
      display: flex;
      align-items: center;
    }

    .slick-slide {
      margin: 0 rem(4) 0;
      position: relative;
      border: 1px solid transparent;
      opacity: 1;
      &:first-child {
        margin-left: 0;
      }
      img {
        width: 100%;
      }
      &.slick-current {
        img {
          opacity: 1;
        }
      }
      &.slick-current,
      &:focus,
      &:hover {
        figure {
          position: relative;
          &:after {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba($blue, 0.2);
          }
        }
      }
    }

    .slick-prev {
      display: none !important;
    }

    .slick-next {
      cursor: pointer;
      position: absolute;

      opacity: 1;
      top: 7px;
      right: 4%;
      width: 21px;
      height: calc(100% - 10px);
      background-size: 21px;
      background-position-x: 60%;
      color: $primary;
      text-align: center;
      i {
        font-size: 35px;
        display: block;
        position: absolute;
        top: 50%;
        left: 50%;
        @include transform(translate(-50%, -50%));
      }
      &:focus,
      &:hover {
        opacity: 0.8;
        background-size: 21px;
      }
    }

    /*.slick-prev,
    .slick-next {
      cursor: pointer;
      position: absolute;
      
      opacity: 1;
      top: 46%;
      width: 12%;
      height: calc(100% - 10px);
      background-size: 21px;
      background-position-x: 60%;
      color: transparent;
      text-align: center;
      img {
        display: block;
        position: absolute;
        top: 50%;
        left: 50%;
        @include transform(translate(-50%, -50%));
      }
      &:focus,
      &:hover {
        opacity: 0.8;
      }
    }

    .slick-next {
      right: 0 !important;
    }

    .slick-prev {
      left: 0 !important;
    }*/
  }

  .slider-for {
    .slick-slide {
      a {
        z-index: -1;
      }
      img {
        width: 100%;
      }
      &.slick-active {
        a {
          z-index: 1;
        }
      }
    }

    .slick-track {
      display: flex;
      align-items: center;
    }
  }

  .slick-slide > div > div {
    display: flex !important;
    align-items: center;
    > a {
      display: inline-block;
    }
  }
  @include media-breakpoint-up(lg) {
    &.igwc-left {
