    @include transition(all 0.25s linear);
  }
  &:after {
    content: "";
    width: calc(100% + 30px);
    height: 100%;
    background-color: rgba($black, 0.5);
    position: absolute;
    top: 0;
    left: rem(-15);
    opacity: 0;
    @include transition(all 0.25s linear);
  }
  &:hover,
  &:focus {
    .cobm-text {
      height: auto;
      visibility: visible;
      opacity: 1;
    }
    &:after {
      opacity: 1;
    }
  }
  &:focus:not(:active):not(:hover) {
    outline: none;
    &:before {
      opacity: 1;
    }
  }
