.ctm-section {
  background: $pdf-color-surface;
  width: 100%;
  padding-bottom: $pdf-section-padding-y;
}

/* --- Tab Bar --- */
.ctm-tabs {
  display: flex;
  gap: 2px;
  width: 100%;
}

.ctm-tab {
  flex: 1 0 0;
  min-width: 0;
  height: 88px;
  background: $pdf-color-primary-dark;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 28px 16px;
  border: none;
  cursor: pointer;
  position: relative;
  overflow: visible;
  color: $pdf-color-on-dark;
  font-family: $pdf-font-family;
  font-weight: $pdf-card-title-weight;
  font-size: $pdf-card-title-size;
  line-height: $pdf-card-title-line-height;
  white-space: nowrap;
  transition: background 0.25s ease;
  isolation: isolate;
}

.ctm-tab:not(.is-active):hover {
  background: $pdf-color-primary;
}

.ctm-tab.is-active {
  overflow: visible;
  cursor: default;
}

/* Mũi tên tam giác dưới tab active */
.ctm-tab__arrow {
  display: none;
  position: absolute;
  bottom: -15px;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  width: 30px;
  height: 30px;
  background: $pdf-color-primary-dark;
  z-index: 2;
}

.ctm-tab.is-active .ctm-tab__arrow {
  display: block;
}

/* Icon trong tab */
.ctm-tab__icon {
  flex-shrink: 0;
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ctm-tab__icon svg {
  width: 28px;
  height: 28px;
  fill: $pdf-color-on-dark;
}

/* --- Tab Content --- */
.ctm-content {
  max-width: $pdf-container-width;
  margin: $pdf-section-padding-y auto 0;
  position: relative;
}

.ctm-panel {
  display: none;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  animation: ctmFadeIn 0.35s ease;
}

.ctm-panel.is-active {
  display: flex;
}

@keyframes ctmFadeIn {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* -- Cột trái: Thông tin -- */
.ctm-info {
  width: 498px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.ctm-info__title {
  font-family: $pdf-font-family;
  font-weight: $pdf-heading-weight;
  font-size: $pdf-heading-size;
  line-height: $pdf-heading-line-height;
  color: $pdf-color-text;
  text-transform: capitalize;
  margin: 0;
}

.ctm-info__desc {
  font-family: $pdf-font-family;
  font-weight: $pdf-body-weight;
  font-size: $pdf-body-size;
  line-height: $pdf-body-line-height;
  color: $pdf-color-text;
  margin: 0;
}

.ctm-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 8px 12px;
  background: $pdf-color-primary;
  color: $pdf-color-on-dark;
  border-radius: $pdf-radius-sm;
  font-family: $pdf-font-family;
  font-weight: $pdf-link-weight;
  font-size: $pdf-button-size;
  line-height: $pdf-button-line-height;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition:
    background 0.2s ease,
    transform 0.15s ease;
  align-self: flex-start;
}

.ctm-btn:hover {
  background: $pdf-color-primary-dark;
  color: $pdf-color-on-dark;
  transform: translateY(-1px);
  text-decoration: none;
}

/* -- Cột phải: Visual (subcategory + image) -- */
.ctm-visual {
  width: 600px;
  height: 300px;
  flex-shrink: 0;
  position: relative;
}

/* Hình ảnh */
.ctm-image {
  position: absolute;
  top: 0;
  right: 0;
  width: 300px;
  height: 300px;
  border-radius: $pdf-radius-sm;
  overflow: hidden;
}

.ctm-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: $pdf-radius-sm;
}

/* Danh sách Subcategory */
.ctm-subcats {
  position: absolute;
  left: 0;
  top: 35px;
  width: 300px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Subcategory cha (active) */
.ctm-subcat-parent {
  display: flex;
  align-items: center;
  gap: 0;
  text-decoration: none;
}

.ctm-subcat-parent__text {
  font-family: $pdf-font-family;
  font-weight: $pdf-link-weight;
  font-size: $pdf-body-size;
  line-height: $pdf-body-line-height;
  color: $pdf-color-primary;
}

.ctm-subcat-parent__arrow {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ctm-subcat-parent__arrow svg {
  width: 9px;
  height: 16px;
  fill: $pdf-color-primary;
}

/* Đường kẻ phân cách */
.ctm-divider {
  width: 100%;
  height: 1px;
  background: #ccc;
}

/* Subcategory con */
.ctm-subcat-children {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-left: 32px;
}

.ctm-subcat-child {
  font-family: $pdf-font-family;
  font-weight: $pdf-link-weight;
  font-size: $pdf-body-size;
  line-height: $pdf-body-line-height;
  color: $pdf-color-text;
  text-decoration: none;
  transition: color 0.2s ease;
}

.ctm-subcat-child:hover {
  color: $pdf-color-primary;
  text-decoration: none;
}

/* ===== Responsive ===== */
@media (max-width: 1200px) {
  .ctm-content {
    max-width: 100%;
    padding: 0 20px;
    margin-top: 60px;
  }
}

@media (max-width: 991px) {
  .ctm-panel {
    flex-direction: column;
    align-items: flex-start;
  }

  .ctm-info,
  .ctm-visual {
    width: 100%;
  }

  .ctm-visual {
    height: auto;
    min-height: 320px;
  }

  .ctm-tab {
    font-size: 18px;
    padding: 20px 10px;
    height: 72px;
  }

  .ctm-tab__icon {
    width: 36px;
    height: 36px;
  }

  .ctm-tab__icon svg {
    width: 22px;
    height: 22px;
  }
}

@media (max-width: 767px) {
  .ctm-tabs {
    flex-direction: column;
    gap: 1px;
  }

  .ctm-tab {
    height: 60px;
    font-size: 16px;
  }

  .ctm-tab__arrow {
    display: none !important;
  }

  .ctm-section {
    padding-bottom: 40px;
  }

  .ctm-content {
    margin-top: 30px;
  }

  .ctm-visual {
    position: static;
    display: flex;
    flex-direction: column-reverse;
    gap: 20px;
  }

  .ctm-image,
  .ctm-subcats {
    position: static;
    width: 100%;
  }

  .ctm-image {
    height: 220px;
  }
}

