  }

  .pdf-news__intro {
    align-items: flex-start;
    display: flex;
    flex-direction: column;
    gap: rem(24);
    padding-right: rem(28);

    @include media-breakpoint-down(lg) {
      padding-right: 0;
      margin-bottom: rem(40);
