      text-decoration: none;
      transition: all 0.3s ease;

      &:hover {
        background: #731219;
        transform: translateY(rem(-2));
      }
    }
  }

  .pdf-news-carousel {
    position: relative;
    width: 100%;
  }

  .pdf-news-carousel__track {
    display: grid;
    gap: rem(20);
    grid-auto-columns: calc((100% - #{rem(40)}) / 3);
    grid-auto-flow: column;
    overflow-x: auto;
    scroll-behavior: smooth;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
    padding-bottom: rem(10);

    &::-webkit-scrollbar {
      display: none;
    }

    @include media-breakpoint-down(md) {
      grid-auto-columns: 100%;
    }
  }

  .pdf-news-card {
    align-items: flex-end;
    background-image: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.8) 100%),
      var(--news-image);
    background-position: center;
    background-size: cover;
    border-radius: rem(3);
    display: flex;
    height: rem(382);
    overflow: hidden;
    position: relative;
    scroll-snap-align: start;
    text-decoration: none;
    transition: transform 0.4s ease;

    &::before {
      background: rgba(0, 0, 0, 0.4);
      content: "";
      inset: 0;
      opacity: 0;
      position: absolute;
      transition: opacity 0.3s ease;
      z-index: 1;
    }

    .pdf-news-card__content {
      color: $white;
      padding: rem(30) rem(12);
      position: relative;
      text-align: center;
      width: 100%;
      z-index: 2;
    }

    .pdf-news-card__title {
      color: $white;
      font-family: $pdf-font-family;
      font-size: rem(21);
      font-weight: 600;
      line-height: rem(28);
      margin: 0;
    }

    .pdf-news-card__description {
      color: $white;
      font-size: rem(15);
      line-height: rem(22);
      margin: rem(12) 0 0;
      max-height: 0;
      opacity: 0;
      overflow: hidden;
      transition: all 0.4s ease;
    }

    &:hover,
    &:focus {
      &::before {
        opacity: 1;
      }

      .pdf-news-card__description {
        max-height: rem(100);
        opacity: 1;
      }
    }
  }

  .pdf-news-carousel__controls {
    display: flex;
    flex-direction: column;
    gap: rem(12);
    position: absolute;
    right: rem(-24);
    top: 50%;
    transform: translateY(-50%);
    z-index: 10;

    @include media-breakpoint-down(lg) {
      position: static;
      flex-direction: row;
      justify-content: center;
      margin-top: rem(20);
      transform: none;
    }
  }

  .pdf-slider-button {
    background: #a91c23;
    border: none;
    border-radius: rem(3);
    cursor: pointer;
    height: rem(48);
    position: relative;
    transition: all 0.3s ease;
    width: rem(48);

    &::after {
      border-right: rem(3) solid $white;
      border-top: rem(3) solid $white;
      content: "";
      height: rem(14);
      left: 50%;
      position: absolute;
      top: 50%;
      transform: translate(-65%, -50%) rotate(45deg);
      width: rem(14);
    }

    &.pdf-slider-button--prev::after {
      transform: translate(-35%, -50%) rotate(-135deg);
    }

    &:hover {
      background: #731219;
      transform: scale(1.05);
    }
  }
}


.pdf-slider-button--prev::before {
  transform: translate(-40%, -50%) rotate(-135deg);
}

