/*========================================================================
 Carousel With Content (hero-cwc)
=========================================================================*/
.hero-cwc {
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  position: relative;
  min-height: rem(800);
  display: flex;
  align-items: center;

  .cwc-container {
    z-index: 1;
    position: relative;
  }
}

/*========================================================================
 Video Section Custom (video_section_module)
=========================================================================*/
.pdf-video {
  background: #333;
  padding: rem(100) 0;

  .pdf-video__inner {
    margin: 0 auto;
    max-width: $pdf-container-width;
  }

  .pdf-video__frame {
    border-radius: rem(3);
    display: block;
    overflow: hidden;
    position: relative;
    width: 100%;
    text-decoration: none;
  }

  .pdf-video__overlay {
    background: rgba(0, 0, 0, 0.4);
    inset: 0;
    position: absolute;
    transition: background-color 180ms ease;
  }

  .pdf-video__content {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 10;
    width: 100%;
    padding: rem(32);
    pointer-events: none;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
  }

  .pdf-video__play,
  .pdf-video__play-icon {
    position: static;
    display: inline-block;
    transform: none;
    margin-bottom: rem(24);
    width: rem(160);
    height: rem(160);
  }

  .pdf-video__title {
    font-size: rem(24);
    font-weight: 600;
    line-height: rem(28);
    color: $white;
    margin: 0;
    font-family: $pdf-font-family;
  
  }

  @include media-breakpoint-down(md) {
    padding: rem(60) 0;
    .pdf-video__frame {
      height: auto;
      aspect-ratio: 16 / 9;
    }
    .pdf-video__play,
    .pdf-video__play-icon {
      width: rem(80);
      height: rem(80);
      margin-bottom: rem(12);
    }
    .pdf-video__title {
      font-size: rem(18);
      line-height: rem(22);
    }
  }


}

